function batterybox(){const left=panel('电池箱健康状况',`<div class="metric-hero">${img('battery')}<div><span>当前 SOC</span><b>98.56<small>%</small></b></div></div>`+metrics([['额定容量','9000','kWh'],['换电充电次数','8'],['插枪充电次数','17'],['累计静置时长','3','h']],'two compact'),'BATTERY HEALTH')+panel('近7次电池箱 SOC',chart('bars',[57,69,82,68,33,80,64],['1次','2次','3次','4次','5次','6次','7次']),'SOC HISTORY')+panel('七日换电充电统计',`<div class="box-stat-list">${[['累计充电量','1786','kWh'],['累计放电量','1520','kWh'],['累计充电次数','83','次'],['累计服务里程','62015','km']].map(([l,v,u])=>`<div><span>${l}</span><b>${v}<small>${u}</small></b></div>`).join('')}</div>`,'ENERGY STATISTICS');const right=panel('实时电压电流',`<div class="box-gauges">${[['680.4','实时电压 / V','voltage'],['338.8','实时电流 / A','current']].map(([v,l,id])=>`<div><svg viewBox="0 0 150 110" aria-hidden="true"><defs><linearGradient id="gauge-${id}"><stop stop-color="#417b9d"/><stop offset="1" stop-color="#9ae8ed"/></linearGradient></defs><path d="M20 90A60 60 0 1 1 130 90" fill="none" stroke="#123442" stroke-width="9"/><path d="M20 90A60 60 0 1 1 130 90" fill="none" stroke="url(#gauge-${id})" stroke-width="6" stroke-dasharray="208 300"/><path d="M75 70L112 41" stroke="#c1f1f7" stroke-width="2"/><circle cx="75" cy="70" r="5" fill="#b2e5ef"/></svg><b id="box-${id}">${v}</b><span>${l}</span></div>`).join('')}</div>`,'REALTIME')+panel('24小时电压电流趋势','<div id="box-chart"></div>','VOLTAGE / CURRENT')+panel('故障信息',`<table class="alarm-table"><thead><tr><th>序号</th><th>故障描述</th></tr></thead><tbody>${['电芯温度过高报警','单体电压过高报警','电池一致性差报警','SOC过高报警','充电储能系统不匹配报警','单体电压过高报警'].map((v,i)=>`<tr><td>0${i+1}</td><td>${v}</td></tr>`).join('')}</tbody></table>`,'FAULT RECORDS');$('suite-main').innerHTML=`<div class="suite-grid box-layout"><aside class="suite-left">${left}</aside><section class="suite-center box-center"><div class="suite-toolbar"><div><h2>电池箱运行监测</h2><small>BATTERY ENERGY SYSTEM / 152456120068</small></div><a class="suite-button" href="?page=battery">返回电池监测 ↗</a></div><div class="batterybox-scene"><img src="./assets/energy/batterybox-wire.svg" alt="电池箱透明透视示意，包含散热风扇、电池模组及高压线路"><span class="wire-caption">BATTERY SYSTEM / X-RAY VIEW <small>结构与内部连接为视觉示意</small></span></div><section class="panel batterybox-info"><div class="panel-title"><h2>电池详细信息</h2><span>BATTERY DETAILS</span></div><div class="body"><div>${pairs([['电池箱编号','152456120068'],['电池类型','其他'],['生产商','宁德时代'],['运营商','山西科达自控股份有限公司']])}</div><div class="box-live"><span>SOC <b>35.68<small>%</small></b></span><span>温度 <b>21.54<small>℃</small></b></span><em><i class="live-dot"></i> 服务中</em></div></div></section></section><aside class="suite-right">${right}</aside></div>`;boxChart();}
function boxChart(){const volts=[224,224,224,224,224,224,224,224,224,224,224,224,224],amps=[125,157,224,112,168,207,106,224,99,154,173,160,198+(tick%7)];const points=v=>v.map((n,i)=>`${i?'L':'M'}${25+i*22} ${142-n*.46}`).join(' ');$('box-chart').innerHTML=`<div class="fine"> <span style="color:#8bd9e7">● 电压</span>　<span style="color:#c8ad7e">● 电流</span></div><svg class="suite-chart" viewBox="0 0 310 175" aria-label="24小时电压电流趋势，原稿示例曲线">${[0,1,2,3].map(i=>`<path d="M25 ${30+i*37}H300" stroke="#315567" stroke-dasharray="2 4"/>`).join('')}<path d="${points(volts)}" fill="none" stroke="#8bd9e7" stroke-width="1.4"/><path d="${points(amps)}" fill="none" stroke="#c8ad7e" stroke-width="1.4"/>${[0,4,8,12,16,20,24].map((n,i)=>`<text x="${25+i*44}" y="168" text-anchor="middle">${n}</text>`).join('')}</svg>`;}

function station(){const stats=[['当前车辆','晋AW072W'],['运营天数','150'],['注册车辆','56'],['排队车辆','5'],['总仓位数','8'],['充电中电池','3'],['可换电池','5'],['检修仓数','0']];$('suite-main').innerHTML=`<div class="station-workspace"><aside class="suite-left">${panel('站点设备',metrics([['大车位置','32'],['小车位置','30'],['升降位置','38']],'compact')+`<div class="thin-rule"></div>${[['换电机器人','正常'],['RFID','正常'],['云平台','异常']].map(([k,v])=>`<div class="device-line"><span>${k}</span><b class="${v==='异常'?'warning':''}">${v}</b></div>`).join('')}`,'EQUIPMENT')}${panel('充换电统计',tabs('station-period',['当日','当月','累计'])+'<div id="station-chart">'+chart('bars',[54,100,76],['换电量','充电量','换电次数'])+'</div>','ENERGY')}${panel('实时监控',cameras(),'MONITORING')}</aside><div class="station-content"><div class="suite-toolbar"><div><h2>山阴 2 号换电站</h2><small>取仓位 02 / 放仓位 05 · 车辆已上锁</small></div><div class="suite-tabs"><button data-mode="flat" class="${mode==='flat'?'active':''}">平面站控</button><button data-mode="3d" class="${mode==='3d'?'active':''}">立体站控</button><button id="equipment">设备启停</button></div></div><div class="station-kpis">${stats.map(([l,v])=>`<div><span>${l}</span><b>${v}</b></div>`).join('')}</div><section class="station-stage panel"><div class="stage-controls"><span><i class="live-dot"></i> 自动模式 · 当前步骤：行车到空电池仓</span><span>STATION DIGITAL VIEW / 场景示意</span></div><div class="stepper">${['进站','车辆到位','换电中','完成','出站'].map((n,i)=>`<span class="${i===2?'active':''}">0${i+1}　${n}</span>`).join('')}</div><div class="station-floor">${mode==='3d'?`<img class="station-model" src="./assets/energy/station-wire.svg" alt="八仓换电站、重卡与龙门吊的等轴测场景"><span class="model-note">2.5D 工程场景 · 点击下方仓位查看状态</span>`:`<div class="station-truck">${img('truck')}<b>晋AW072W</b><small>车辆已到位 / 等待换电</small></div><div class="floor-bays">${socs.map((v,i)=>`<button class="bay" data-bay="${i}"><span>0${i+1} / 电池仓</span>${img('battery')}<strong>${v===null?'—':v+'%'}</strong><span>${v===null?'待机中':v===100?'已完成':'充电中'}</span><div class="soc-track"><i style="width:${v||0}%"></i></div><small>${i===5?'连接器异常':'烟感正常 · R传感器正常'}</small></button>`).join('')}</div>`}</div>${mode==='3d'?`<div class="mini-bays">${socs.map((v,i)=>`<button data-bay="${i}">0${i+1} / ${i===5?'连接器异常':'电池仓'}<b>${v===null?'待机':v+'%'}</b></button>`).join('')}</div>`:''}</section>${panel('告警信息',alarms(),'EQUIPMENT ALERTS','station-alarms')}</div></div>`;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;station();});document.querySelectorAll('[data-bay]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.bay);open(`${i+1}号电池仓`,`<div class="dialog-hero">${img('battery')}${pairs([['电池编号','1221415985'],['SOC',socs[i]===null?'暂无电池':socs[i]+'%'],['仓位状态',socs[i]===null?'待机中':socs[i]===100?'已完成':'充电中'],['烟感','正常'],['R传感器','正常'],['连接器',i===5?'异常':'正常']])}</div>`);});document.querySelectorAll('[data-station-period]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.stationPeriod);stationPeriod=i;activate(b,'[data-station-period]');$('station-chart').innerHTML=chart('bars',[54,100,76].map(v=>Math.round(v*[1,1.25,1.6][i])),['换电量','充电量','换电次数']);});$('equipment').onclick=()=>{open('设备启停',`<p class="detail-help">作品集操作演示，不连接实际换电设备。</p><div class="vehicle-actions"><button class="suite-button" data-control="停止">停止演示</button><button class="suite-button primary" data-control="启动">启动演示</button></div>`);document.querySelectorAll('[data-control]').forEach(b=>b.onclick=()=>{paused=b.dataset.control==='停止';syncPause();$('suite-dialog').close();toast('设备演示已'+b.dataset.control);});};}
function activate(button,selector){document.querySelectorAll(selector).forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});}
function regional(markers){return `<img class="regional-map" src="./assets/energy/regional-scene.svg" alt="站点及车辆区域分布示意底图"><div class="map-markers">${markers.map(([label,icon,x,y,key,offline])=>`<button class="map-marker ${offline?'offline':''}" style="left:${x}%;top:${y}%" data-marker="${key}">${img(icon)}<b>${label}</b></button>`).join('')}</div><span class="map-scene-note">运行 / 停止 / 离线　·　区域位置与道路为演示示意</span>`;}
function searchForm(){return '<form class="map-search" id="map-search"><input id="search-input" aria-label="电池ID、车牌号或联系电话" placeholder="搜索电池 ID / 车牌号 / 联系电话"><button class="suite-button" type="submit">搜索</button></form>';}
const batteryItems=Array.from({length:14},(_,i)=>({id:i%3===0?'1221415985':'1221415680',soc:i%3===0?85:100,station:i<7?'山阴站':'韩家楼站',bay:i%7+1}));
function inventory(items,vehicle=false){return `<div class="inventory-grid">${items.map((r,i)=>`<button class="inventory-item ${vehicle&&i%3===1?'offline':''}" data-battery="${vehicle?'vehicle':batteryItems.indexOf(r)}">${img('battery')}<strong>${vehicle?'85':r.soc}%</strong><em>${vehicle?(i%3===1?'离线':'在线'):r.soc===100?'充满':'充电中'}</em><span>${vehicle?'晋F00029D':r.bay+'号仓'}</span><span>${vehicle?'12214568062':r.id}</span></button>`).join('')}</div>`;}
function battery(){const left=panel('在站电池',`<div class="battery-summary">${[['总数','14'],['可换','8'],['不可换','6']].map(([k,v])=>`<div><span>${k}</span><b>${v}</b></div>`).join('')}</div><div class="filter-row"><select id="battery-station" aria-label="筛选站点"><option>全部站点</option><option>山阴站</option><option>韩家楼站</option></select></div><div class="battery-list" id="battery-list"></div>`,'STATION BATTERIES');const right=panel('车辆电池',`<div class="battery-summary">${[['总数','18'],['电量高于45%','12'],['电量低于45%','6']].map(([k,v])=>`<div><span>${k}</span><b>${v}</b></div>`).join('')}</div><div class="filter-row"><select id="fleet" aria-label="筛选车队"><option>忻州五寨</option><option>朔州</option></select></div><div class="inventory-block"><h3 id="fleet-name">忻州五寨 <small>车辆电池示例</small></h3>${inventory(Array.from({length:7},()=>({})),true)}</div><p class="fine">运行 / 停止 / 离线 · 状态分别呈现</p>`,'VEHICLE BATTERIES');$('suite-main').innerHTML=`<div class="suite-grid"><aside class="suite-left">${left}</aside><section class="suite-center map-body">${regional([['山阴站','station',33,33,'station'],['韩家楼站','station',61,67,'station'],['1221415985','battery',55,36,'battery'],['晋F00029D','truck',46,67,'vehicle'],['离线电池','battery',78,51,'battery',true]])}${searchForm()}</section><aside class="suite-right">${right}</aside></div>`;function render(){const value=$('battery-station').value;$('battery-list').innerHTML=['山阴站','韩家楼站'].filter(n=>value==='全部站点'||value===n).map(n=>`<div class="inventory-block"><h3>${n}<small>总数 7 / 可换 4 / 不可换 3</small></h3>${inventory(batteryItems.filter(r=>r.station===n))}</div>`).join('');bindBatteries();}render();$('battery-station').onchange=render;$('fleet').onchange=()=>$('fleet-name').innerHTML=esc($('fleet').value)+' <small>车辆电池示例</small>';document.querySelectorAll('[data-marker]').forEach(b=>b.onclick=()=>batteryDetail());$('map-search').onsubmit=e=>{e.preventDefault();const v=$('search-input').value.trim();if(!v)return toast('请输入电池 ID、车牌号或联系电话');if(['1221415985','1221415680','晋F00029D','12214568062'].some(s=>s.includes(v)))batteryDetail();else toast('没有匹配的演示记录');};}
