function trajectory(){trackPosition=0;trackSpeed=1;open('车辆轨迹',pairs([['车牌号','晋J-0186D / 待装载'],['所属公司','山西科达自控股份有限公司'],['司机','李民桥'],['联系电话','132****3721']])+`<div class="track-controls"><label>日期 <input id="track-date" type="date" value="2024-03-07"></label><button class="suite-button" id="track-back">回到起点</button><button class="suite-button" id="track-play">播放</button><label>速度 <select id="track-speed"><option value="1">1X</option><option value="8">8X</option><option value="32">32X</option></select></label><input class="trace-progress" id="track-range" type="range" min="0" max="100" value="0" aria-label="轨迹播放进度"></div><div class="track-stage"><img src="./assets/energy/regional-scene.svg" alt="车辆历史轨迹示意底图"><svg viewBox="0 0 800 340"><path d="M90 260L265 250 360 140 560 135 690 75" fill="none" stroke="#0a1826" stroke-width="12"/><path d="M90 260L265 250 360 140 560 135 690 75" fill="none" stroke="#8dcad8" stroke-width="3"/><g id="track-truck"><image href="./assets/energy/iso-truck.svg" x="-31" y="-48" width="62" height="62"/></g></svg></div><p class="detail-help" id="track-note">轨迹为演示示意，支持播放、暂停、倍速和拖动进度；原稿未提供真实轨迹数据。</p>`);function update(){const pts=[[90,260],[265,250],[360,140],[560,135],[690,75]],v=trackPosition/25,i=Math.min(3,Math.floor(v)),t=v-i;const x=pts[i][0]+(pts[i+1][0]-pts[i][0])*t,y=pts[i][1]+(pts[i+1][1]-pts[i][1])*t;$('track-truck').setAttribute('transform',`translate(${x} ${y})`);$('track-range').value=trackPosition;}update();$('track-play').onclick=()=>{trackPlaying=!trackPlaying;$('track-play').textContent=trackPlaying?'暂停':'播放';};$('track-speed').onchange=e=>trackSpeed=Number(e.target.value);$('track-back').onclick=()=>{trackPosition=0;update();};$('track-range').oninput=e=>{trackPosition=Number(e.target.value);update();};$('track-date').onchange=()=>{trackPlaying=false;$('track-play').textContent='播放';trackPosition=0;update();$('track-note').textContent='所选日期：'+$('track-date').value+'。暂无真实轨迹数据，地图仅播放示意路线。';};trackTimer=setInterval(()=>{if(!trackPlaying||paused||document.hidden)return;trackPosition=Math.min(100,trackPosition+.25*trackSpeed);if(trackPosition===100){trackPlaying=false;$('track-play').textContent='播放';}update();},100);}
const chargeStates=['充电中','空闲','已充满','故障','离线'];function charging(){const left=panel('站点概览',`<div class="metric-hero">${img('station')}<div><span>充电枪总数</span><b>36</b></div></div>`+metrics([['充电中','2'],['未充电','34'],['额定功率','5760','kW'],['实时功率','131.76','kW'],['功率满足率','2.28','%']],'two compact'),'STATION')+panel('充电趋势',tabs('charging-trend',['充电量趋势','充电订单趋势'],trendMode)+`<div id="charging-chart">${chargingChart()}</div>`,'CHARGING TREND')+panel('实时监控',cameras(),'MONITORING');$('suite-main').innerHTML=`<div class="workload-grid"><aside class="suite-left">${left}</aside><div class="charging-content"><div class="suite-toolbar"><div><h2>特来电屯留小河北重卡充电站</h2><small>充电设备与订单运行态势</small></div><span class="fine">STATION ENERGY CONTROL</span></div><div class="charging-kpis">${[['今日充电量 / 度','12035'],['本月充电量 / 度','44.8'],['本年充电量 / 万度','360.5'],['今日充电订单','12035'],['本月充电订单','2300']].map(([l,v])=>`<div><span>${l}</span><b>${v}</b></div>`).join('')}</div><div class="charging-state">${[['全部','36'],['空闲','26'],['充电中','26'],['已充满','2'],['离线','2'],['故障','0'],['其他','0']].map(([l,v])=>`<button data-charge-filter="${l}" class="${chargeFilter===l?'active':''}">${l}<b>${v}</b></button>`).join('')}</div><div class="charger-grid" id="charger-grid"></div><div class="charger-pages" id="charger-pages"></div>${panel('告警信息',alarms(),'EQUIPMENT ALERTS','station-alarms')}</div></div>`;renderChargers();document.querySelectorAll('[data-charge-filter]').forEach(b=>b.onclick=()=>{chargeFilter=b.dataset.chargeFilter;chargePage=1;activate(b,'[data-charge-filter]');renderChargers();});document.querySelectorAll('[data-charging-trend]').forEach(b=>b.onclick=()=>{trendMode=Number(b.dataset.chargingTrend);activate(b,'[data-charging-trend]');$('charging-chart').innerHTML=chargingChart();});}
function chargingChart(){if(trendMode)return chart('line',[150,122,150,108,106,261,152+tick%9],['12','13','14','15','16','17','18']);const colors=['#7682b3','#6baeb0','#669bbc','#b49372'];return `<div class="fine">${['尖','峰','平','谷'].map((n,i)=>`<span style="color:${colors[i]};margin-right:12px">■ ${n}</span>`).join('')}</div><svg class="suite-chart" viewBox="0 0 300 170" role="img" aria-label="充电量趋势，按尖峰平谷分组，演示数据">${[0,1,2,3].map(i=>`<path d="M25 ${20+i*40}H295" stroke="#34556b" stroke-dasharray="2 5"/><text x="0" y="${23+i*40}">${16000-i*5000}</text>`).join('')}${['08/14','08/16','08/18'].map((label,j)=>`<text x="${74+j*88}" y="160" text-anchor="middle">${label}</text>${[1600,2800,7800,13000].map((v,i)=>{const h=(v+(j===2?tick%20*15:0))/16000*120,x=44+j*88+i*14;return `<rect x="${x}" y="${140-h}" width="9" height="${h}" fill="${colors[i]}"/><path d="M${x} ${140-h}h9" stroke="#c2dbe5" stroke-opacity=".6"/>`;}).join('')}`).join('')}</svg>`; }
function renderChargers(){const all=Array.from({length:36},(_,i)=>({id:i+1,status:chargeStates[i%5]})),filtered=all.filter(x=>chargeFilter==='全部'||x.status===chargeFilter),pages=Math.max(1,Math.ceil(filtered.length/15));chargePage=Math.min(chargePage,pages);$('charger-grid').innerHTML=filtered.slice((chargePage-1)*15,chargePage*15).map(r=>`<button class="charger ${r.status==='故障'?'fault':r.status==='离线'?'offline':''}" data-charger="${r.id}"><span>${String(r.id).padStart(3,'0')}B号 / 直流</span>${img('station')}<b>${r.status==='充电中'?'80%':r.status==='已充满'?'100%':r.status}</b><em>${r.status}</em><small>${['充电中','已充满'].includes(r.status)?'陕A0G266 · 310.2 kWh':'—'}</small></button>`).join('')||'<p class="empty-state">当前筛选下没有演示设备</p>';$('charger-pages').innerHTML=Array.from({length:pages},(_,i)=>`<button data-charge-page="${i+1}" class="${i+1===chargePage?'active':''}">${i+1}</button>`).join('')+'<span class="fine">原稿统计与设备状态示例分别保留</span>';document.querySelectorAll('[data-charge-page]').forEach(b=>b.onclick=()=>{chargePage=Number(b.dataset.chargePage);renderChargers();});document.querySelectorAll('[data-charger]').forEach(b=>b.onclick=()=>{const r=all[Number(b.dataset.charger)-1];open(`${String(r.id).padStart(3,'0')}B号 · 充电设备`,`<div class="dialog-hero">${img('station')}${pairs([['交直流','直流'],['设备状态',r.status],['车牌号',['充电中','已充满'].includes(r.status)?'陕A0G266':'—'],['电量',['充电中','已充满'].includes(r.status)?'310.2 kWh':'—'],['SOC',r.status==='充电中'?'80%':r.status==='已充满'?'100%':'—'],['剩余时间',r.status==='充电中'?'0时12分':'—']])}</div>`);});}
